// single-item input: the form emits one submission, and everything below is
// about that one supplier.
//
// Read the form by name, not from $input. `Settings` sits between the two and a
// Set node in manual mode *replaces* the item, so $input here is the settings
// object and every form field would be undefined - which surfaces as the
// "enter the supplier website" error on a submission that filled it in.
const f = $('Vet A Supplier').first().json;

function host(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/[\/?#].*$/, '')
    .replace(/^.*@/, '');   // accepts a whole email address in the domain field
}

const site = host(f['Their website']);
const invoiceDomain = host(f['Domain the invoice email came from']);

if (!site) {
  throw new Error('Enter the supplier website you already know is genuine - it is the thing everything else is compared against.');
}

return [{ json: {
  supplier: String(f['Supplier or company name'] || '').trim(),
  site,
  site_url: 'https://' + site,
  invoice_domain: invoiceDomain,
  // Fetching the apex of a domain that is only used for mail is normal and
  // often empty; that is a signal, not a failure, and is read as such below.
  invoice_url: invoiceDomain ? 'https://' + invoiceDomain : '',
  amount: String(f['Amount on the invoice'] || '').trim(),
  raised_by: String(f['Your name'] || '').trim(),
  // The exact phrase the complaint search runs. Quoted, so a two-word supplier
  // name is matched as a name rather than as two loose words.
  complaint_query:
    '"' + String(f['Supplier or company name'] || '').replace(/"/g, '') + '"' +
    ' (scam OR fraud OR complaint OR lawsuit OR "did not deliver")',
}}];

// What a real company's site carries and a shell company's does not.
//
// None of these is proof on its own. Together they separate a business with a
// registered address and a terms page from a template site stood up last month,
// which is the whole question when an invoice arrives from a name you half
// recognise.
//
// single-item input: one form submission means one supplier and one page, so
// this branch carries exactly one response to read.
const req = $('Read The Request').first().json;
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

// Measured 2026-08-23: real company sites returned 9.7-76 KB of markdown
// through the Unlocker, a domain that does not exist returned 0 bytes.
const reachable = !!md && md.length > 500;

const signals = {
  privacy_page: /\]\([^)]*privacy/i.test(md),
  terms_page: /\]\([^)]*(terms|conditions|\/tos)/i.test(md),
  phone: /\+?\d[\d\s().-]{8,}\d/.test(md),
  email: /[\w.-]+@[\w.-]+\.\w{2,}/.test(md),
  postal_address: /\b(street|avenue|road|suite|floor|blvd|str\.|st\.)\b/i.test(md),
  company_number: /\b(vat|company (no|number|reg)|registration number|siret|ein)\b/i.test(md),
  careers_or_about: /\]\([^)]*(about|team|careers|jobs)/i.test(md),
};

const present = Object.keys(signals).filter((k) => signals[k]);
const missing = Object.keys(signals).filter((k) => !signals[k]);

return [{ json: {
  check: 'website',
  site: req.site,
  site_reachable: reachable,
  site_bytes: md.length,
  signals_present: present,
  signals_missing: missing,
  trust_points: present.length,
  trust_max: Object.keys(signals).length,
  // Kept short deliberately: this feeds a model prompt, and the whole page
  // would bury the seven things that were actually measured.
  site_extract: String(md).replace(/\s+/g, ' ').slice(0, 600),
}}];

// A raw hit count means nothing - every large company has complaints, and a
// brand new shell has none because nobody has been defrauded yet. What is
// scored is the share of result *titles* that actually carry a fraud word.
//
// single-item input: one supplier, one complaint search, one SERP response.
const req = $('Read The Request').first().json;
let payload = $input.first().json;

// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body`. Reading `organic` off the top level finds nothing and reports a clean
// supplier, which is the wrong direction to fail in. Measured live: the node
// received a 23 KB envelope while `payload.organic` was undefined.
if (payload && payload.body != null) payload = payload.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); } catch (e) { payload = {}; }
} else if (typeof payload.data === 'string') {
  try { payload = JSON.parse(payload.data); } catch (e) { payload = {}; }
}

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response reads as "clean".
const failed = !!(payload && payload.error) || !payload;

const all = (payload && payload.organic) || [];
const HOT = /(scam|fraud|fraudulent|lawsuit|sued|complaint|ripoff|rip-off|did not deliver|never delivered|chargeback|class action|scandal)/i;

// Drop the supplier's own pages before scoring anything.
//
// Not tidying - this is the difference between a check people trust and one
// they switch off. Measured live 2026-08-23: searching Stripe returned "Submit
// a Complaint" and "Managing fraudulent transactions", both stripe.com support
// pages about protecting merchants *from* fraud, and they pushed a legitimate
// company to 7 flagged results out of 9. Any company that sells fraud
// protection ranks for fraud words on its own domain. Evidence against a
// supplier has to come from somewhere other than the supplier.
function host(u) {
  const m = String(u || '').match(/^https?:\/\/([^/?#]+)/);
  return m ? m[1].toLowerCase().replace(/^www\./, '') : '';
}
function core(d) { return String(d || '').split('.').slice(-2).join('.'); }

const own = core(req.site);
const organic = all.filter((o) => core(host(o && o.link)) !== own);
const own_pages = all.length - organic.length;

const flagged = [];
for (const o of organic.slice(0, 12)) {
  const title = String((o && o.title) || '').replace(/\s+/g, ' ').trim();
  const link = String((o && o.link) || '');
  if (!title) continue;
  if (HOT.test(title)) flagged.push({ title: title.slice(0, 140), link });
}

return [{ json: {
  check: 'complaints',
  supplier: req.supplier,
  search_ran: !failed,
  results_read: organic.length,
  own_pages_ignored: own_pages,
  flagged_count: flagged.length,
  // A single angry blog post is noise; half the first page is not.
  flagged_share: organic.length ? Math.round((flagged.length / organic.length) * 100) : 0,
  flagged: flagged.slice(0, 5),
}}];

// The bank-detail-change check, and the one that catches real money going out.
//
// Edit distance between the invoice's domain and the website you already trust
// catches the whole lookalike class at once: str1pe.com, stripe-billing.com,
// stripe.co. No WHOIS key, no paid feed, about fifteen lines.
//
// single-item input: one invoice domain per submission, so one response.
const req = $('Read The Request').first().json;
const raw = $input.first().json;
const md = typeof raw === 'string' ? raw : (raw.data || raw.body || '');

function distance(a, b) {
  a = String(a); b = String(b);
  const rows = [];
  for (let i = 0; i <= b.length; i++) rows[i] = [i];
  for (let j = 0; j <= a.length; j++) rows[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      rows[i][j] = b.charAt(i - 1) === a.charAt(j - 1)
        ? rows[i - 1][j - 1]
        : Math.min(rows[i - 1][j - 1] + 1, rows[i][j - 1] + 1, rows[i - 1][j] + 1);
    }
  }
  return rows[b.length][a.length];
}

// Compare the registrable part, so mail.stripe.com is not read as a lookalike
// of stripe.com just for being longer.
function core(d) { return String(d || '').split('.').slice(-2).join('.'); }

const site = req.site;
const inv = req.invoice_domain;

const same = !!inv && core(inv) === core(site);
const gap = (!inv || same) ? 0 : distance(core(inv), core(site));
// One or two edits away from the domain you trust is the signature of a
// lookalike. Far away is simply a different company - a shared mailbox, an
// agency, an accountant - which is a question, not an alarm.
const lookalike = !!inv && !same && gap > 0 && gap <= 3;

return [{ json: {
  check: 'invoice_domain',
  invoice_domain: inv,
  site,
  invoice_domain_given: !!inv,
  same_domain: same,
  edit_distance: gap,
  lookalike,
  // Empty body = the domain did not resolve. Note the one confounder: Bright
  // Data returns empty for brightdata.com too, because it declines to scrape
  // itself - so this is reported as "did not respond", not as "does not exist".
  invoice_domain_responded: !!md && md.length > 500,
  invoice_bytes: md.length,
}}];

// Turn the three checks into one number and, more importantly, into a list of
// reasons a person can argue with.
//
// Read the three by name rather than from $input: the Merge above is an
// ordering barrier, and its output order is not something to depend on.
const req = $('Read The Request').first().json;
const web = $('Read The Trust Signals').first().json;
const comp = $('Read The Complaints').first().json;
const dom = $('Read The Domain Answer').first().json;

const reasons = [];
let risk = 0;

// --- the invoice domain. This is the expensive one, so it is weighted hardest.
if (dom.invoice_domain_given) {
  if (dom.lookalike) {
    risk += 45;
    reasons.push('The invoice domain ' + dom.invoice_domain + ' is ' + dom.edit_distance +
      ' character' + (dom.edit_distance === 1 ? '' : 's') + ' away from ' + dom.site +
      '. That is the signature of a lookalike domain.');
  } else if (!dom.same_domain) {
    risk += 15;
    reasons.push('The invoice came from ' + dom.invoice_domain + ', not ' + dom.site +
      '. That can be an accountant or an agency, but it should be confirmed.');
  }
  if (!dom.invoice_domain_responded && !dom.same_domain) {
    risk += 20;
    reasons.push('The invoice domain did not return a page. A mail-only domain is normal; a domain registered last week to send one invoice looks the same.');
  }
} else {
  reasons.push('No invoice domain was given, so the lookalike check did not run.');
}

// --- the website
if (!web.site_reachable) {
  risk += 25;
  reasons.push('Their website could not be read at all.');
} else {
  const thin = web.trust_max - web.trust_points;
  if (thin >= 5) {
    risk += 25;
    reasons.push('The site carries almost none of the things a trading company usually publishes. Missing: ' + web.signals_missing.join(', ') + '.');
  } else if (thin >= 3) {
    risk += 12;
    reasons.push('The site is missing several ordinary trust signals: ' + web.signals_missing.join(', ') + '.');
  }
}

// --- complaints
if (!comp.search_ran) {
  reasons.push('The complaint search did not complete, so nothing was checked there.');
} else if (comp.flagged_share >= 40) {
  risk += 25;
  reasons.push(comp.flagged_count + ' of the first ' + comp.results_read + ' results are about fraud, scams or lawsuits.');
} else if (comp.flagged_count > 0) {
  risk += 10;
  reasons.push(comp.flagged_count + ' result' + (comp.flagged_count === 1 ? '' : 's') + ' mention fraud or complaints, out of ' + comp.results_read + '.');
}

if (!reasons.length) reasons.push('Nothing on any of the three checks looked wrong.');

risk = Math.max(0, Math.min(100, risk));
const band = risk >= 60 ? 'high' : risk >= 30 ? 'medium' : 'low';

return [{ json: Object.assign({}, req, {
  risk_score: risk,
  risk_band: band,
  reasons,
  website: web,
  complaints: comp,
  domain: dom,
  checked_at: $now.toISO(),
}) }];

parameters.text:
=You are a finance controller writing two or three sentences for a colleague who has to decide whether to pay an invoice in the next few minutes.

Supplier: {{ $json.supplier }}
Website they are known by: {{ $json.site }}
Domain the invoice email came from: {{ $json.invoice_domain || 'not given' }}
Risk score: {{ $json.risk_score }} out of 100 ({{ $json.risk_band }})

What the checks found:
{{ JSON.stringify($json.reasons) }}

Website signals present: {{ JSON.stringify($json.website.signals_present) }}
Website signals missing: {{ JSON.stringify($json.website.signals_missing) }}
Flagged search results: {{ JSON.stringify($json.complaints.flagged) }}

Say what the strongest single concern is and what would settle it. If the domain check found a lookalike, lead with that and say so plainly - it is the one that costs money.

Be specific and stay inside the findings above. Do not invent a fact, a date or a company detail that is not there. If the checks found nothing wrong, say that clearly rather than manufacturing a doubt - a false alarm on every supplier is how this gets switched off.

Never tell them to approve or to block. Someone else decides that. Return the sentences only, plain prose, no headings and no bullet points.

