// A chain node replaces the item with its answer, so the whole check would be
// gone by the time the approval message is built.
//
// single-item input: the chain runs executeOnce, so it emits one verdict for
// the one supplier being checked.
const scored = $('Score The Risk').first().json;
const raw = $input.first().json || {};

let verdict = String(raw.text || raw.response || raw.output || '').trim();
// Slack reads one asterisk as bold and prints two literally.
verdict = verdict.replace(/\*\*([^*\n]+)\*\*/g, '*$1*');

return [{ json: Object.assign({}, scored, {
  verdict: verdict || 'The model returned nothing - read the measured findings below and decide on those.',
}) }];

// The audit trail is the point of writing this down at all: months later the
// question is never "what was the score" but "who released this payment".
//
// single-item input: the wait node resumes with exactly one item, the click.
const check = $('Attach The Verdict').first().json;
const answer = $input.first().json || {};
const decision = (answer.data && answer.data.approved) === true;

return [{ json: {
  supplier: check.supplier || check.site,
  site: check.site,
  invoice_domain: check.invoice_domain || '',
  risk_score: check.risk_score,
  risk_band: check.risk_band,
  decision: decision ? 'approved' : 'blocked',
  // The wait node returns the moment a button was clicked. If nobody clicked
  // and the wait timed out, this is the timeout instant and `approved` is
  // false - which is the safe direction for a payment.
  decided_at: (answer.data && answer.data.respondedAt) || $now.toISO(),
  raised_by: check.raised_by || '',
  amount: check.amount || '',
  verdict: String(check.verdict || '').slice(0, 900),
  reasons: (check.reasons || []).join(' | ').slice(0, 900),
}}];
